Given a sorted array arr[] and a list of queries represented as a 2D array queries[][]. Each query is a triplet of the form [l, r, x], where l and r are indices in the array, and x is the value to search for.For each query, find how many times the number x appears in the subarray arr[l...r] (inclusive).Examples:Input: arr[] = [1, 2, 2, 4, 5, 5, 5, 8], queries[][] = [[0, 7, 5], [1, 2, 2], [0, 3, 7]]Output: [3, 2, 0]Explanation:Query [0, 7, 5] → elements from index 0 to 7 are [1, 2, 2, 4, 5, 5, 5, 8]. Number 5 occurs 3 times.Query [1, 2, 2] → subarray is [2, 2], and 2 occurs 2 times.Query [0, 3, 7] → subarray is [1, 2, 2, 4], and 7 is not present → 0.Input: arr[] = [1, 3, 3, 3, 6, 7, 8], queries[][] = [[0, 3, 3], [4, 6, 3], [1, 5, 6]]Output: [3, 0, 1]Explanation:Query [0, 3, 3] → subarray [1, 3, 3, 3], and 3 appears 3 times.Query [4, 6, 3] → subarray [6, 7, 8], 3 not found → 0.Query [1, 5, 6] → subarray [3, 3, 3, 6, 7], and 6 occurs 1 time.Try It YourselfTable of Content[Naive Approach] Naive Linear Scan - O(q × n) Time and O(1) Space [Expected Approach] Using Binary Search[Naive Approach] Naive Linear Scan - O(q × n) Time and O(1) Space For each query, iterate through the subarray from index l to r, and count how many times x appears.
            C++

    #include <iostream>
#include <vector>
using namespace std;

vector<int> countXInRange(vector<int>& arr, 
                    vector<vector<int>>& queries) {
    vector<int> result;

    for (auto& query : queries) {
        int l = query[0];
        int r = query[1];
        int x = query[2];
        int count = 0;

        // check every index from l to r
        for (int i = l; i <= r; i++) {
            if (arr[i] == x)
                count++;
        }

        result.push_back(count);
    }

    return result;
}

int main() {
    vector<int> arr = {1, 2, 2, 4, 5, 5, 5, 8};
    vector<vector<int>> queries = {
        {0, 7, 5},
        {1, 2, 2},
        {0, 3, 7}
    };

    vector<int> res = countXInRange(arr, queries);
    for (int count : res)
        cout << count << " ";
    cout << endl;

    return 0;
}


