[Expected Approach] Using Binary SearchThe idea is to use binary search (lower_bound and upper_bound) to find the first and last positions where the element x appears in the sorted array. Once we know all the positions where x occurs, we simply check how many of those lie within the given index range [l, r]. If there's no overlap between the index range of occurrences and the query's [l, r], we return 0. Otherwise, we return the number of overlapping positions, which is right - left + 1.Step by Step Implementation:For each query [l, r, x], extract l, r, and x.Use lower_bound to find the first index where x could appear.If x doesn't exist in the array, directly store 0 as the answer for this query.Use upper_bound to find the first index where the value becomes greater than x; subtract 1 to get the last index of x.Clamp the range of x's occurrences to within [l, r] using max(left, l) and min(right, r).If the clamped range is valid (left ≤ right), count the occurrences as right - left + 1.Otherwise, store 0 for this query.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> countXInRange(vector<int>& arr, 
                         vector<vector<int>>& queries) {

    vector<int> result;
    int n = arr.size();

    for (auto& query : queries) {
        int l = query[0];
        int r = query[1];
        int x = query[2];

        // find first index where arr[i] == x
        int left = lower_bound(arr.begin(), arr.end(), x)
                   - arr.begin();

        // if x is not present at all
        if (left == n || arr[left] != x) {
            result.push_back(0);
            continue;
        }

        // find first index where arr[i] > x
        int right = upper_bound(arr.begin(), arr.end(), x)
                    - arr.begin();

        // last index where arr[i] == x
        right--; 

        // clip the indices to [l, r]
        left = max(left, l);
        right = min(right, r);

        // if no overlap
        if (left > right)
            result.push_back(0);
        else
            result.push_back(right - left + 1);
    }

    return result;
}

int main() {
    vector<int> arr = {1, 2, 2, 4, 5, 5, 5, 8};
    vector<vector<int>> queries = {
        {0, 7, 5},
        {1, 2, 2},
        {0, 3, 7}
    };

    vector<int> res = countXInRange(arr, queries);
    for (int count : res)
        cout << count << " ";
    cout << endl;

    return 0;
}


