    using System;
using System.Collections.Generic;

class GfG {
    public static List<int>
            countXInRange(int[] arr, int[][] queries) {

        List<int> result = new List<int>();
        int n = arr.Length;

        foreach (var query in queries) {
            int l = query[0];
            int r = query[1];
            int x = query[2];

            // find first index where arr[i] == x
            int left = LowerBound(arr, x);

            // if x is not present at all
            if (left == n || arr[left] != x) {
                result.Add(0);
                continue;
            }

            // find first index where arr[i] > x
            int right = UpperBound(arr, x);
            right--; // last index where arr[i] == x

            // clip the indices to [l, r]
            left = Math.Max(left, l);
            right = Math.Min(right, r);

            // if no overlap
            if (left > right)
                result.Add(0);
            else
                result.Add(right - left + 1);
        }

        return result;
    }

    private static int LowerBound(int[] arr, int x) {
        int low = 0, high = arr.Length;
        while (low < high) {
            int mid = (low + high) / 2;
            if (arr[mid] < x) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    private static int UpperBound(int[] arr, int x) {
        int low = 0, high = arr.Length;
        while (low < high) {
            int mid = (low + high) / 2;
            if (arr[mid] <= x) low = mid + 1;
            else high = mid;
        }
        return low;
    }

